-- Seed the next three authored A2 Unit 1 lessons in sequence.
-- Focus: irregular preterite, imperfect background, integrated past narration.
insert into public.lessons(unit_id,slug,title,description,lesson_type,estimated_minutes,sequence,learning_objectives,content,points_reward,is_published)
select u.id,v.slug,v.title,v.description,v.lesson_type,v.estimated_minutes,v.sequence,v.learning_objectives,v.content,v.points_reward,true
from public.course_units u
cross join (values
('usar-verbos-irregulares-en-el-pasado','Talk about what happened: irregular preterite','Use the most useful irregular preterite verbs to explain what happened, what you did, and how a situation changed.','core',35,2,'["Recognize and produce the high-frequency irregular preterite forms fui, hice, tuve, estuve, pude, puse, vine, dije, and quise","Use irregular stems with the correct shared endings","Choose a verb based on meaning rather than translating word by word","Tell a connected story using at least five irregular past-tense verbs"]'::jsonb,'{"sections":[{"body":"In real conversations, people often explain what happened using a small group of irregular verbs: fui (I went/was), hice (I did/made), tuve (I had), pude (I was able to), and dije (I said). These forms appear constantly. Today you will learn them as useful verb families, then use them to explain a problem and its outcome.","type":"intro","title":"Talk about what happened","eyebrow":"01 · COMMUNICATIVE GOAL"},{"note":"Learn the meaning and the past form together. Notice that fui can mean “I went” or “I was”; the surrounding words tell you which meaning fits.","type":"vocabulary","items":[{"term":"ir → fui","example":"Fui al centro después del trabajo.","meaning":"to go → I went"},{"term":"ser → fui","example":"La reunión fue muy útil.","meaning":"to be → I was"},{"term":"hacer → hice","example":"Hice una llamada importante.","meaning":"to do / make → I did / made"},{"term":"tener → tuve","example":"Tuve un problema con el auto.","meaning":"to have → I had"},{"term":"estar → estuve","example":"Estuve en casa toda la tarde.","meaning":"to be / be located → I was"},{"term":"poder → pude","example":"Pude resolver el problema.","meaning":"to be able to → I managed to"},{"term":"poner → puse","example":"Puse los documentos en la mesa.","meaning":"to put / place → I put"},{"term":"venir → vine","example":"Vine temprano para ayudar.","meaning":"to come → I came"},{"term":"decir → dije","example":"Le dije la verdad.","meaning":"to say / tell → I said"},{"term":"querer → quise","example":"Quise llamarte, pero no tuve tiempo.","meaning":"to want / try → I wanted / tried"}],"title":"Nine verbs worth knowing","eyebrow":"02 · MEANING FIRST"},{"text":"Ayer tuve un día complicado. Primero, fui al trabajo temprano porque tenía una reunión. Cuando llegué, vi que no tenía los documentos. Estuve buscando en mi mochila y después hice una llamada a mi compañero. Él me dijo que los documentos estaban en su oficina. Quise ir por ellos, pero no pude salir porque tenía que terminar una presentación. Al mediodía, vino mi compañera y puso los documentos sobre mi escritorio. Por fin, pude terminar el trabajo y fui a casa más tranquilo.","type":"reading","title":"Un día complicado","eyebrow":"03 · NOTICE THE VERBS","glossary":[["tuve","I had"],["fui","I went"],["estuve buscando","I was searching"],["me dijo","he told me"],["quise","I wanted / tried"],["no pude","I couldn''t / wasn''t able to"],["vino","he/she came"],["puso","he/she put"],["pude terminar","I managed to finish"]],"instructions":"Read aloud twice. On the second reading, identify each irregular verb and ask what information it adds to the story."},{"body":"Many common irregular preterite verbs change their stem. The useful shortcut: several of them share the same endings, and those endings do not carry written accents.","note":"Ir and ser share the exact same preterite forms: fui, fuiste, fue, fuimos, fueron. Context decides the meaning. Poder often means “managed to” when it is affirmative (pude hacerlo), but “couldn''t” in the negative (no pude hacerlo).","type":"grammar","steps":["Identify the infinitive and its meaning.","Use the irregular stem: tener → tuv-, hacer → hic-, poder → pud-.","Add the shared ending: -e, -iste, -o, -imos, -ieron.","Check the subject and the context before choosing the meaning."],"table":{"rows":[["yo","tuve","hice","pude"],["tú","tuviste","hiciste","pudiste"],["él / ella / usted","tuvo","hizo","pudo"],["nosotros","tuvimos","hicimos","pudimos"],["ellos / ustedes","tuvieron","hicieron","pudieron"]],"columns":["Subject","tener → tuv-","hacer → hic-","poder → pud-"],"heading":"Shared endings for many irregular preterites"},"title":"Irregular stems, shared endings","eyebrow":"04 · FORM AND FUNCTION","pattern":"SUBJECT + IRREGULAR STEM + PRETERITE ENDING","examples":[["Ayer tuve una reunión.","Yesterday I had a meeting."],["Hicimos la reservación por teléfono.","We made the reservation by phone."],["No pude llegar a tiempo.","I couldn''t arrive on time."],["Ella dijo que sí.","She said yes."]],"patternExample":"yo + tuv- + e → tuve · ellos + pud- + ieron → pudieron"},{"type":"practice","title":"Choose the verb that tells the story","eyebrow":"05 · GUIDED RETRIEVAL","questions":[{"rule":"tener → tuv- + yo ending -e","retry":"El lunes yo _____ una reunión importante.","answer":"tuve","prompt":"Ayer yo _____ mucho trabajo.","options":["tuve","tuvo","tuvieron"],"explanation":"The subject is yo. The irregular stem is tuv- and the yo ending is -e: tuve.","retryAnswer":"tuve"},{"rule":"hacer → hic-; él/ella form is hizo","retry":"Mi hermano _____ la cena anoche.","answer":"hizo","prompt":"Mi hermana _____ una torta para la fiesta.","options":["hice","hizo","hicieron"],"explanation":"Mi hermana is ella. The third-person singular form is hizo (not hició).","retryAnswer":"hizo"},{"rule":"poder → pud- + nosotros ending -imos","retry":"Ayer nosotros no _____ encontrar el lugar.","answer":"pudimos","prompt":"Nosotros no _____ llegar antes de las ocho.","options":["pude","pudimos","pudieron"],"explanation":"Nosotros requires pudimos. No pude/pudimos means “couldn''t / weren''t able to.”","retryAnswer":"pudimos"},{"rule":"decir → dij-; ellos form is dijeron","retry":"Mis amigos _____ que estaban cansados.","answer":"dijeron","prompt":"Ellos _____ la verdad durante la conversación.","options":["dije","dijo","dijeron"],"explanation":"The subject is ellos. Decir uses the irregular stem dij- and the third-person plural form dijeron.","retryAnswer":"dijeron"},{"rule":"ir → fui for yo","retry":"Complete: Ayer yo _____ al supermercado.","answer":"Fui a la oficina.","prompt":"Which sentence means “I went to the office”?","options":["Fui a la oficina.","Fue a la oficina.","Fuimos a la oficina."],"explanation":"Fui is the yo form of ir. Fue is él/ella/usted; fuimos is nosotros.","retryAnswer":"fui"}],"instructions":"Choose the form that matches the subject and meaning. Read the explanation, then complete the similar retry sentence."},{"type":"production","model":"Ayer tuve un problema con mi computadora. Fui a una tienda, pero no pudieron ayudarme inmediatamente. Llamé a un amigo y él me dijo que podía revisar el equipo. Vino a mi casa por la tarde e hizo algunas pruebas. Al final, pudo encontrar el problema y yo pude terminar mi trabajo. Le di las gracias porque me ayudó mucho.","title":"Explain a problem and its outcome","eyebrow":"06 · INDEPENDENT SPEAKING AND WRITING","prompts":["What happened at the beginning?","Where did you go, and who was there?","What did you do or say?","What couldn''t you do at first?","How did the situation end?"],"checklist":["I used at least five irregular preterite forms.","My verbs match the subject.","I used a time marker or connector to organize the events.","I explained the outcome, not just a list of actions."],"instructions":"Write 6–8 connected sentences about a day when something did not go as planned. Then read your story aloud twice. Use the prompts to organize the story, not as separate one-word answers."},{"type":"assessment","title":"Use the irregular forms accurately","eyebrow":"07 · MASTERY CHECK","questions":[{"rule":"hacer → hizo for él/ella/usted","retry":"La directora _____ una pregunta.","answer":"hizo","prompt":"Ayer mi jefe _____ una decisión importante.","options":["hice","hizo","hicieron"],"explanation":"Mi jefe is third-person singular, so the correct form is hizo.","retryAnswer":"hizo"},{"rule":"ir → fuimos for nosotros","retry":"El sábado nosotros _____ al centro.","answer":"fuimos","prompt":"Nosotros _____ al museo el domingo.","options":["fui","fuimos","fueron"],"explanation":"The subject nosotros takes fuimos. The same form can also be ser, depending on context.","retryAnswer":"fuimos"},{"rule":"poder → pude for yo","retry":"Anoche yo no _____ dormir bien.","answer":"pude","prompt":"Yo no _____ terminar el informe ayer.","options":["pude","pudo","pudieron"],"explanation":"The subject is yo, so use pude. No pude means “I couldn''t / wasn''t able to.”","retryAnswer":"pude"},{"rule":"venir → vinieron for ellos","retry":"Mis primos _____ a cenar el viernes.","answer":"vinieron","prompt":"Mis vecinos _____ temprano a la reunión.","options":["vine","vino","vinieron"],"explanation":"Mis vecinos is plural. The correct third-person plural form is vinieron.","retryAnswer":"vinieron"},{"rule":"decir → dijo for él/ella/usted","retry":"Mi amigo me _____ que estaba ocupado.","answer":"dijo","prompt":"Which form completes: “Ella me _____ la verdad” (decir)?","options":["dije","dijo","dijeron"],"explanation":"Ella takes dijo. Notice that decir has the irregular stem dij-.","retryAnswer":"dijo"}],"instructions":"Choose the best answer for each item. You need at least 4 out of 5 to pass. Review the rule and retry the parallel example when you miss one."}],"objective":"Explain what happened in a real situation by choosing and using high-frequency irregular preterite verbs accurately.","estimatedMinutes":35}'::jsonb,35),
('describir-contexto-y-habitos-en-el-pasado','Set the scene: the imperfect tense','Describe past routines, ongoing situations, age, time, and background details with the imperfect.','core',35,3,'["Recognize when the imperfect describes habits, repeated actions, and background","Conjugate regular imperfect forms for -ar, -er, and -ir verbs","Use the three major irregular imperfect forms: era, iba, and veía","Describe a past routine or setting with specific supporting details"]'::jsonb,'{"sections":[{"body":"Not every past sentence reports a finished event. Sometimes you want to describe what life was like, what you used to do, or what was happening around an event. Spanish often uses the imperfect for this background information. Think of it as the camera view of the past: routines, descriptions, age, time, and ongoing situations.","type":"intro","title":"Set the scene in the past","eyebrow":"01 · COMMUNICATIVE GOAL"},{"note":"These expressions often appear with the imperfect because they describe repeated or ongoing situations. They are clues, not automatic rules: the meaning of the whole sentence still matters.","type":"vocabulary","items":[{"term":"antes","example":"Antes vivía cerca del centro.","meaning":"before / back then"},{"term":"cuando era niño/a","example":"Cuando era niño, jugaba afuera.","meaning":"when I was a child"},{"term":"todos los días","example":"Todos los días caminábamos a la escuela.","meaning":"every day"},{"term":"cada verano","example":"Cada verano visitábamos a mis abuelos.","meaning":"every summer"},{"term":"normalmente","example":"Normalmente cenábamos a las ocho.","meaning":"normally / usually"},{"term":"a menudo","example":"A menudo veía a mis primos.","meaning":"often"},{"term":"mientras","example":"Mientras mi mamá cocinaba, yo estudiaba.","meaning":"while"},{"term":"tener ... años","example":"Tenía diez años.","meaning":"to be ... years old"}],"title":"Phrases that signal a past routine","eyebrow":"02 · TIME AND DESCRIPTION CHUNKS"},{"text":"Cuando tenía diez años, vivía con mis abuelos en una casa cerca de Guadalajara. La casa era grande y tenía un patio con muchos árboles. Durante la semana, me levantaba temprano y caminaba a la escuela con mi primo. Mi abuela preparaba el desayuno y mi abuelo leía el periódico en la cocina. Por las tardes, jugábamos fútbol en la calle mientras los vecinos hablaban afuera. Los domingos, normalmente visitábamos a otros familiares. No teníamos muchas cosas, pero siempre había algo que hacer y la familia pasaba mucho tiempo junta.","type":"reading","title":"Cuando vivía con mis abuelos","eyebrow":"03 · READ FOR BACKGROUND","glossary":[["tenía diez años","I was ten years old"],["vivía","I used to live / was living"],["era grande","it was big"],["me levantaba","I used to get up"],["preparaba","she used to prepare"],["leía","he used to read"],["jugábamos","we used to play"],["había","there was / there were"]],"instructions":"Read aloud twice. Notice which sentences describe repeated habits or the setting, rather than one completed event."},{"body":"Use the imperfect to describe repeated past actions, ongoing situations, age, time, feelings, and background conditions. It does not present the action as one completed event.","note":"The imperfect is not simply “the tense for long actions.” A short state can use the imperfect (Tenía hambre), while a long but completed event can use the preterite (Viví allí cinco años). Focus on how the speaker presents the event: background/habit or bounded completed event.","type":"grammar","steps":["Use -aba for regular -ar verbs: hablar → hablaba.","Use -ía for regular -er and -ir verbs: comer → comía; vivir → vivía.","Memorize the three irregular forms: ser → era, ir → iba, ver → veía.","Use the imperfect for habits, descriptions, age, time, and ongoing background."],"table":{"rows":[["yo","hablaba","comía","vivía"],["tú","hablabas","comías","vivías"],["él / ella / usted","hablaba","comía","vivía"],["nosotros","hablábamos","comíamos","vivíamos"],["ellos / ustedes","hablaban","comían","vivían"]],"columns":["Subject","-AR · hablar","-ER · comer","-IR · vivir"],"heading":"Regular imperfect endings"},"title":"The imperfect: habits and background","eyebrow":"04 · GRAMMAR IN CONTEXT","pattern":"SUBJECT + IMPERFECT VERB + BACKGROUND DETAIL","examples":[["De niño, jugaba en el parque.","As a child, I used to play in the park."],["Mi familia vivía en Puebla.","My family lived in Puebla."],["Mientras yo estudiaba, mi hermano cocinaba.","While I was studying, my brother was cooking."],["Eran las nueve y hacía frío.","It was nine o''clock and it was cold."]],"patternExample":"Cuando era pequeño, vivía cerca del mar y nadaba todos los días."},{"type":"practice","title":"Describe what life was like","eyebrow":"05 · GUIDED RETRIEVAL","questions":[{"rule":"Past setting or ongoing state → imperfect","retry":"Cuando tenía ocho años, yo _____ cerca de la escuela.","answer":"vivía","prompt":"Cuando era niño, yo _____ en un pueblo pequeño.","options":["vivía","viví","vivo"],"explanation":"The sentence describes where the person lived during childhood, a background situation. Use vivía.","retryAnswer":"vivía"},{"rule":"Repeated past habit → imperfect","retry":"Cada invierno nosotros _____ a mis abuelos.","answer":"visitábamos","prompt":"Todos los veranos nosotros _____ a nuestros primos.","options":["visitamos","visitábamos","visitaremos"],"explanation":"Todos los veranos signals a repeated habit in the past, so visitábamos is the natural choice.","retryAnswer":"visitábamos"},{"rule":"Regular -er verb in imperfect → -ía","retry":"Mi padre _____ un libro antes de dormir.","answer":"leía","prompt":"Mi abuelo _____ el periódico después del desayuno.","options":["leía","leyó","lee"],"explanation":"The sentence describes what the grandfather regularly did after breakfast. Leer becomes leía.","retryAnswer":"leía"},{"rule":"ser → era for description in the past","retry":"La ciudad _____ más pequeña antes.","answer":"era","prompt":"Cuando vivíamos allí, la casa _____ muy tranquila.","options":["fue","era","es"],"explanation":"The sentence describes a characteristic of the house during that period. Use era.","retryAnswer":"era"},{"rule":"Ongoing background action → imperfect","retry":"Mientras mi mamá cocinaba, yo _____.","answer":"estudiaba","prompt":"Mientras yo _____, mi hermana escuchaba música.","options":["estudiaba","estudié","estudio"],"explanation":"Mientras introduces an action in progress that forms the background. Estudiaba is the imperfect.","retryAnswer":"estudiaba"}],"instructions":"Choose the form that expresses a repeated habit or background description."},{"type":"production","model":"Cuando era adolescente, vivía en una ciudad pequeña. Mi casa estaba cerca de un parque y mis amigos vivían en la misma calle. Todos los días caminábamos juntos a la escuela. Por las tardes, jugábamos básquetbol y después hacíamos la tarea. Mi mamá normalmente preparaba la cena a las siete. Era una rutina sencilla, pero me gustaba mucho.","title":"Describe a place or routine from your past","eyebrow":"06 · INDEPENDENT PRODUCTION","prompts":["Where did you live or spend time?","What was the place like?","What did you usually do?","Who was usually with you?","What was happening around you?"],"checklist":["I used at least five imperfect verbs.","I included a description with era, tenía, or había.","I used a repeated-time phrase such as todos los días or cada verano.","I described a setting instead of listing only completed events."],"instructions":"Write 6–8 sentences describing a real or imagined period in your life. Then read it aloud twice. Focus on giving the listener a clear picture of the setting."},{"type":"assessment","title":"Choose the imperfect in context","eyebrow":"07 · MASTERY CHECK","questions":[{"rule":"Repeated childhood habit → imperfect","retry":"Cuando era joven, mi abuelo _____ mucho.","answer":"leía","prompt":"De pequeño, mi hermano _____ mucho.","options":["leía","leyó","lee"],"explanation":"De pequeño establishes a past period and the sentence describes a habit. Use leía.","retryAnswer":"leía"},{"rule":"Past background situation → imperfect","retry":"Hace años, nosotros _____ en el norte.","answer":"vivíamos","prompt":"Antes, nosotros _____ cerca de la playa.","options":["vivimos","vivíamos","viviremos"],"explanation":"Antes describes a former living situation, not one completed action.","retryAnswer":"vivíamos"},{"rule":"ser → era for background description","retry":"Mi barrio _____ más tranquilo.","answer":"era","prompt":"Mi escuela _____ muy pequeña.","options":["era","fue","es"],"explanation":"The speaker describes the school as it was during a past period. Era is appropriate.","retryAnswer":"era"},{"rule":"Repeated action → imperfect","retry":"Cada domingo mis primos _____ conmigo.","answer":"jugaban","prompt":"Todos los sábados mis amigos _____ fútbol.","options":["jugaban","jugaron","juegan"],"explanation":"Todos los sábados signals a repeated past routine. Use jugaban.","retryAnswer":"jugaban"},{"rule":"iba is the imperfect of ir","retry":"Choose the meaning: “Antes iba al parque cada tarde.”","answer":"A repeated or ongoing past situation","prompt":"What does “Cuando tenía ocho años, iba a esa escuela” communicate?","options":["One trip to the school","A repeated or ongoing past situation","A future plan"],"explanation":"Iba presents a past routine or ongoing situation: “When I was eight, I used to go to that school.”","retryAnswer":"A repeated or ongoing past situation"}],"instructions":"Choose the best form for the meaning. You need at least 4 out of 5 to pass."}],"objective":"Describe what life was like, what used to happen, and what was going on in the background using the imperfect.","estimatedMinutes":35}'::jsonb,35),
('preterito-o-imperfecto-contar-una-historia','Put the past together: preterite or imperfect?','Combine completed events with background descriptions to tell a clear, natural story in the past.','core',40,4,'["Distinguish completed foreground events from background and habitual information","Use the imperfect to set a scene and the preterite to move the story forward","Apply common time and interruption patterns without relying on signal words alone","Produce a connected narrative using both past tenses"]'::jsonb,'{"sections":[{"body":"You now have two tools for talking about the past. The preterite moves the story forward: something happened, began, ended, or changed. The imperfect gives the background: what was going on, what things were like, or what usually happened. Strong storytelling uses both.","type":"intro","title":"Put the past together","eyebrow":"01 · INTEGRATION"},{"note":"These chunks help organize a story, but they do not mechanically choose the tense. Decide whether you are describing the background or reporting a completed event.","type":"vocabulary","items":[{"term":"mientras","example":"Mientras caminaba, empezó a llover.","meaning":"while"},{"term":"de repente","example":"De repente, escuché un ruido.","meaning":"suddenly"},{"term":"en ese momento","example":"En ese momento, llegó el autobús.","meaning":"at that moment"},{"term":"cuando","example":"Cuando era niño, visitaba a mis primos.","meaning":"when"},{"term":"al principio","example":"Al principio, no entendía el problema.","meaning":"at first"},{"term":"al final","example":"Al final, encontramos la salida.","meaning":"in the end"},{"term":"soler + infinitive","example":"Solía caminar por ese parque.","meaning":"to usually do something"},{"term":"de pronto","example":"De pronto, alguien llamó a la puerta.","meaning":"all of a sudden"}],"title":"Connect the background and the event","eyebrow":"02 · STORY CONNECTORS"},{"text":"Era viernes y llovía mucho. Yo caminaba hacia mi casa después del trabajo y las calles estaban casi vacías. Normalmente tomaba el autobús, pero esa noche decidí caminar. Mientras pasaba por una tienda, escuché un ruido fuerte. De repente, un perro salió corriendo de un edificio y cruzó la calle. Un hombre salió detrás de él y gritó su nombre. Yo me detuve y ayudé al hombre a buscarlo. Después de unos minutos, encontramos al perro detrás de un auto. El hombre estaba muy preocupado, pero cuando vio al perro, sonrió y me dio las gracias. Al final, seguí caminando a casa. Todavía llovía, pero ya no tenía prisa.","type":"reading","title":"Una noche inesperada","eyebrow":"03 · STORY STRUCTURE","glossary":[["era viernes","it was Friday"],["llovía","it was raining"],["caminaba","I was walking"],["decidí","I decided"],["escuché","I heard"],["salió corriendo","ran out"],["me detuve","I stopped"],["encontramos","we found"],["seguí caminando","I continued walking"]],"instructions":"Read aloud twice. Mark the background details in one color mentally, and the events that move the story forward in another."},{"body":"Ask one question: am I painting the situation, or reporting what happened? Use the imperfect for the setting, ongoing action, description, and habits. Use the preterite for the completed event that advances the story.","note":"Do not choose only by words like ayer, mientras, or de repente. They can help, but meaning decides. Compare: Llovía cuando salí (It was raining when I left). Llovió toda la noche (It rained all night—viewed as a completed period).","type":"grammar","steps":["Identify the background: what was happening or what was the situation like?","Identify the completed event: what happened and moved the story forward?","Choose the tense based on viewpoint, not just the length of the action.","Read the whole sentence again to make sure the timeline makes sense."],"table":{"rows":[["Background","La calle estaba vacía.","—"],["Ongoing action","Yo caminaba a casa.","—"],["Completed event","—","Escuché un ruido."],["Interruption","Mientras dormía...","...sonó el teléfono."],["Habit vs one event","Antes iba en autobús.","Ayer fui en taxi."]],"columns":["Purpose","Imperfect","Preterite"],"heading":"Compare the speaker''s viewpoint"},"title":"Background versus foreground","eyebrow":"04 · MAKE THE TENSE CHOICE","pattern":"BACKGROUND (IMPERFECT) + EVENT (PRETERITE)","examples":[["Mientras cocinaba, sonó el teléfono.","While I was cooking, the phone rang."],["La gente hablaba cuando empezó la música.","People were talking when the music started."],["Antes vivía en Cali, pero en 2022 me mudé.","I used to live in Cali, but in 2022 I moved."],["Hacía frío y nevaba cuando llegamos.","It was cold and snowing when we arrived."]],"patternExample":"Yo caminaba por el parque cuando vi a una amiga."},{"type":"practice","title":"Choose the viewpoint","eyebrow":"05 · GUIDED TENSE CHOICE","questions":[{"rule":"Ongoing background action → imperfect","retry":"Mientras ella _____, empezó a llover.","answer":"trabajaba","prompt":"Mientras yo _____, mi teléfono sonó.","options":["trabajaba","trabajé","trabajo"],"explanation":"The work was already in progress when the phone rang. Use trabajaba for the background.","retryAnswer":"caminaba"},{"rule":"One completed event → preterite","retry":"El sábado pasado nosotros _____ un partido.","answer":"vimos","prompt":"Ayer nosotros _____ una película y después cenamos.","options":["veíamos","vimos","vemos"],"explanation":"The sentence reports one completed movie-watching event yesterday. Use vimos.","retryAnswer":"vimos"},{"rule":"Description/background → imperfect","retry":"El restaurante _____ pequeño y familiar.","answer":"era","prompt":"La casa _____ muy vieja, pero tenía un jardín bonito.","options":["fue","era","es"],"explanation":"The age of the house is a descriptive background detail. Use era.","retryAnswer":"era"},{"rule":"A sudden completed event → preterite","retry":"De pronto, el perro _____ a correr.","answer":"llamó","prompt":"De repente, alguien _____ a la puerta.","options":["llamaba","llamó","llama"],"explanation":"The knock is a single event that advances the story. Use llamó.","retryAnswer":"empezó"},{"rule":"Former habit/background contrasted with a completed change","retry":"Antes yo _____ cerca del trabajo, pero en 2024 cambié de casa.","answer":"vivía","prompt":"Antes mi familia _____ en una casa, pero el año pasado se mudó.","options":["vivía","vivió","vive"],"explanation":"Vivía describes the former situation. Se mudó reports the completed change.","retryAnswer":"vivía"}],"instructions":"For each sentence, decide whether the verb describes background/habit or a completed event."},{"type":"production","model":"Era sábado por la tarde y hacía mucho calor. Yo estaba en casa y preparaba la cena cuando escuché un golpe en la puerta. Abrí y vi a un vecino que necesitaba ayuda. Su auto no arrancaba, así que busqué unos cables. Salimos al estacionamiento y tratamos de encenderlo. Después de varios minutos, el motor arrancó. Mi vecino me dio las gracias y regresé a la cocina. La comida estaba un poco fría, pero todo salió bien.","title":"Tell a story with a turning point","eyebrow":"06 · NARRATIVE PRODUCTION","prompts":["What day or time was it? What was the weather or setting like?","What were you doing?","What happened suddenly?","What did you do next?","How did the situation end?"],"checklist":["I used at least three imperfect forms for background or description.","I used at least four preterite forms for completed events.","I included a clear interruption or turning point.","The timeline is easy for another person to follow."],"instructions":"Write 8–10 sentences about an unexpected event. Include a clear setting, something that was happening, one event that interrupted it, and an ending. Read it aloud twice after writing."},{"type":"assessment","title":"Tell the difference in context","eyebrow":"07 · CUMULATIVE CHECK","questions":[{"rule":"Ongoing background at the moment another event happened","retry":"Eran las diez y yo _____ cuando sonó la alarma.","answer":"cenábamos","prompt":"Eran las ocho y nosotros _____ en el restaurante cuando llegó Ana.","options":["cenábamos","cenamos","cenaremos"],"explanation":"The dinner was in progress when Ana arrived. Use the imperfect cenábamos.","retryAnswer":"dormía"},{"rule":"Completed change → preterite","retry":"En 2023 mi familia _____ a otra ciudad.","answer":"se mudó","prompt":"El año pasado mi hermano _____ de ciudad.","options":["se mudaba","se mudó","se muda"],"explanation":"The move is a completed event in a finished time frame. Use se mudó.","retryAnswer":"se mudó"},{"rule":"Repeated past habit → imperfect","retry":"De niño, yo _____ fútbol todos los días.","answer":"jugaba","prompt":"Cuando era pequeño, yo _____ con mis primos cada verano.","options":["jugué","jugaba","juego"],"explanation":"Cada verano describes a repeated habit during childhood. Use jugaba.","retryAnswer":"jugaba"},{"rule":"Completed event that interrupts the background → preterite","retry":"Mientras estudiaba, _____ el teléfono.","answer":"empezó","prompt":"Mientras caminábamos, _____ a llover.","options":["empezaba","empezó","empieza"],"explanation":"The rain starting is the event that occurs while the walking is in progress. Use empezó.","retryAnswer":"sonó"},{"rule":"Imperfect state + completed action","retry":"Complete naturally: _____ nervioso, pero _____ a la entrevista.","answer":"Estaba cansado, así que fui a casa.","prompt":"Choose the most natural sentence for “I was tired, so I went home.”","options":["Estaba cansado, así que fui a casa.","Estuve cansado, así que iba a casa.","Estoy cansado, así que fui a casa."],"explanation":"Estaba describes the state/background; fui reports the completed action of going home.","retryAnswer":"Estaba nervioso, pero fui"}],"instructions":"Choose the tense that best communicates the meaning. You need at least 4 out of 5 to pass."}],"objective":"Tell a connected story by setting the scene with the imperfect and moving the events forward with the preterite.","estimatedMinutes":40}'::jsonb,40)
